void gemm(int n, const float *A, const float *B, float *C) {
    if (n != 512) {
        fallback_gemm(n, A, B, C);
        return;
    }
    const void *parameters[22] = {0};
    parameters[4] = B;
    parameters[10] = A;
    parameters[16] = C;

    float *bt = malloc((size_t)512 * 512 * sizeof(float));
    if (!bt) {
        sera_libxsmm_512(parameters);
        return;
    }

    /* Physical bt[k*512+j]=B[j*512+k]. TRANS_A requires transposed B
       in slot 4 and original A in slot 10; output remains original C. */
    sme_transpose(512, B, bt);
    parameters[4] = bt;
    sera_libxsmm_ta(parameters);
    free(bt);
}
